pub assume_specification<'a, T, A: Allocator, F: FnMut(&'a T) -> Ordering>[
    VecDeque::<T, A>::binary_search_by
](
    v: &'a VecDeque<T, A>,
    f: F,
) -> (result: Result<usize, usize>)
    requires
        forall|i: int| 0 <= i < v@.len() ==> f.requires((v@.as_ref()[i],)),
        exists|lo: int, hi: int| {
            &&& 0 <= lo <= hi <= v@.len()
            &&& forall|i: int, ord: Ordering|
                0 <= i < v@.len() && f.ensures((v@.as_ref()[i],), ord) ==> {
                    &&& (i < lo ==> ord == Ordering::Less)
                    &&& (lo <= i < hi ==> ord == Ordering::Equal)
                    &&& (hi <= i ==> ord == Ordering::Greater)
                }
        },
    ensures
        match result {
            Ok(i) => {
                &&& (i as int) < v@.len()
                &&& f.ensures((v@.as_ref()[i as int],), Ordering::Equal)
            },
            Err(i) => {
                &&& (i as int) <= v@.len()
                &&& forall|j: int, ord: Ordering|
                    0 <= j < v@.len() && f.ensures((v@.as_ref()[j],), ord) ==> {
                        &&& (j < i as int ==> ord == Ordering::Less)
                        &&& (i as int <= j ==> ord == Ordering::Greater)
                    }
            },
        },
;

pub assume_specification<'a, T, A: Allocator, B: Ord, F: FnMut(&'a T) -> B>[
    VecDeque::<T, A>::binary_search_by_key
](
    v: &'a VecDeque<T, A>,
    b: &B,
    f: F,
) -> (result: Result<usize, usize>)
    requires
        forall|i: int| 0 <= i < v@.len() ==> f.requires((v@.as_ref()[i],)),
        exists|lo: int, hi: int| {
            &&& 0 <= lo <= hi <= v@.len()
            &&& forall|i: int, key: B, ord: Ordering|
                0 <= i < v@.len()
                && f.ensures((v@.as_ref()[i],), key)
                && call_ensures(<B as Ord>::cmp, (&key, b), ord) ==> {
                    &&& (i < lo ==> ord == Ordering::Less)
                    &&& (lo <= i < hi ==> ord == Ordering::Equal)
                    &&& (hi <= i ==> ord == Ordering::Greater)
                }
        },
    ensures
        match result {
            Ok(i) => {
                &&& (i as int) < v@.len()
                &&& exists|key: B| {
                    &&& f.ensures((v@.as_ref()[i as int],), key)
                    &&& call_ensures(<B as Ord>::cmp, (&key, b), Ordering::Equal)
                }
            },
            Err(i) => {
                &&& (i as int) <= v@.len()
                &&& forall|j: int, key: B, ord: Ordering|
                    0 <= j < v@.len()
                    && f.ensures((v@.as_ref()[j],), key)
                    && call_ensures(<B as Ord>::cmp, (&key, b), ord) ==> {
                        &&& (j < i as int ==> ord == Ordering::Less)
                        &&& (i as int <= j ==> ord == Ordering::Greater)
                    }
            },
        },
;

pub assume_specification<T, A: Allocator>[
    VecDeque::<T, A>::pop_back_if
](
    v: &mut VecDeque<T, A>,
    predicate: impl FnOnce(&mut T) -> bool,
) -> (result: Option<T>)
    requires
        old(v)@.len() > 0 ==> forall|x: &mut T|
            *x == old(v)@[old(v)@.len() - 1] ==> predicate.requires((x,)),
    ensures
        old(v)@.len() == 0 ==> result is None && final(v)@ == old(v)@,
        old(v)@.len() > 0 ==> exists|x: &mut T, take: bool| {
            &&& *x == old(v)@[old(v)@.len() - 1]
            &&& predicate.ensures((x,), take)
            &&& (take ==> {
                &&& result == Some(*final(x))
                &&& final(v)@ == old(v)@.subrange(0, old(v)@.len() - 1)
            })
            &&& (!take ==> {
                &&& result is None
                &&& final(v)@ == old(v)@.update(old(v)@.len() - 1, *final(x))
            })
        },
;

