            &&& predicate.ensures((x,), take)
            &&& (take ==> {
                &&& result == Some(*final(x))
                &&& final(v)@ == old(v)@.subrange(1, old(v)@.len())
            })
            &&& (!take ==> {
                &&& result is None
                &&& final(v)@ == old(v)@.update(0, *final(x))
            })
        },
